import numpy as np
def relu(x):
    return np.maximum(0, x)
result = relu(np.array([-1, 0, 2]))
print(result.sum())

import numpy as np
def softmax(x):
    e_x = np.exp(x - np.max(x))
    return e_x / e_x.sum()
result = softmax(np.array([1, 2, 3]))
print(round(result.sum(), 1))

